const API=(window.APP_CONFIG?.API_BASE_URL||'').replace(/\/$/,'');
let token=sessionStorage.getItem('pilot_token')||'',me=null,staff=[],properties=[],channels=[],bookings=[],charts={},staffMonth='',propertyFilter='',kpiMonth='';
const fmtVND=v=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(v||0));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isoToday=()=>new Date().toISOString().slice(0,10);
function closeModal(id){document.getElementById(id).style.display='none'}
function msg(id,t,c=''){const e=document.getElementById(id);if(e)e.innerHTML=`<div class="notice ${c}">${t}</div>`}
async function api(path,opts={}){const headers={...(opts.headers||{})};if(token)headers.Authorization=`Bearer ${token}`;if(opts.body&&!(opts.body instanceof FormData)){headers['Content-Type']='application/json';opts.body=JSON.stringify(opts.body)}const r=await fetch(API+path,{...opts,headers});if(r.status===401){let m='Unauthorized';try{m=(await r.clone().json()).detail||m}catch{}if(path!='/api/auth/login'){logout();throw new Error('Session expired')}throw new Error(m)}if(!r.ok){let m=`HTTP ${r.status}`;try{m=(await r.json()).detail||m}catch{}throw new Error(m)}const ct=r.headers.get('content-type')||'';return ct.includes('application/json')?r.json():r}
function destroyChart(k){if(charts[k]){charts[k].destroy();delete charts[k]}}
function mkChart(id,key,type,labels,data,label='',opts={}){destroyChart(key);const el=document.getElementById(id);if(!el)return;charts[key]=new Chart(el,{type,data:{labels,datasets:[{label,data}]},options:{responsive:true,maintainAspectRatio:false,...opts}})}
function mkMultiChart(id,key,type,labels,datasets,opts={}){destroyChart(key);const el=document.getElementById(id);if(!el)return;charts[key]=new Chart(el,{type,data:{labels,datasets},options:{responsive:true,maintainAspectRatio:false,...opts}})}
async function download(path,filename){const headers={};if(token)headers.Authorization=`Bearer ${token}`;const r=await fetch(API+path,{headers});if(r.status===401){logout();throw new Error('Session expired')}if(!r.ok){let m=`HTTP ${r.status}`;try{m=(await r.clone().json()).detail||m}catch{}throw new Error(m)}const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function score(v){return v==null?'N/A':Number(v).toFixed(1)+'%'}
function kpiStatus(v){if(v==null)return 'N/A';return v>=90?'Excellent':v>=80?'Good':v>=70?'Fair':'Needs Improvement'}
async function login(){try{const j=await api('/api/auth/login',{method:'POST',body:{username:document.getElementById('login-user').value.trim(),password:document.getElementById('login-pass').value}});token=j.access_token;sessionStorage.setItem('pilot_token',token);await boot()}catch(e){msg('login-msg',esc(e.message),'error')}}
function logout(){sessionStorage.removeItem('pilot_token');token='';me=null;document.getElementById('app-view').classList.add('hidden');document.getElementById('login-view').classList.remove('hidden')}
async function boot(){if(!token)return;try{me=await api('/api/auth/me');document.getElementById('login-view').classList.add('hidden');document.getElementById('app-view').classList.remove('hidden');document.getElementById('whoami').textContent=`Signed in: ${me.username} — ${me.full_name} (${me.role})`;buildNav();await loadMasters();showView('dashboard')}catch(e){logout()}}
function buildNav(){let d=[['dashboard','📈 Dashboard'],['staff','👥 Staff'],['kpi','🏆 KPI Dashboard']];if(['manager','admin'].includes(me.role))d.push(['datamodel','🧩 Data Model']);d.push(['channels','🌐 Channels'],['segments','👨‍👩‍👧‍👦 Segments'],['financial','💰 Financial'],['stays','🏨 Stay Duration'],['bookings','📅 Bookings'],['properties','🏢 Properties']);if(me.role==='admin')d.push(['import','📥 Import']);if(['manager','admin'].includes(me.role))d.push(['export','📤 Export'],['auditlog','📋 Audit Log'],['validation','✅ Validation']);if(me.role==='admin')d.push(['auditpanel','🔍 Audit Panel'],['users','🔐 Users']);document.getElementById('nav').innerHTML=d.map(([i,l])=>`<button id="nav-${i}" onclick="showView('${i}')">${l}</button>`).join('')}
async function loadMasters(){[staff,properties,channels]=await Promise.all([api('/api/staff'),api('/api/properties'),api('/api/channels')])}
function showView(id){document.querySelectorAll('.view').forEach(x=>x.classList.add('hidden'));document.getElementById(id).classList.remove('hidden');document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));document.getElementById(`nav-${id}`)?.classList.add('active');const f={dashboard:loadDashboard,staff:loadStaff,kpi:loadKPI,datamodel:loadDataModel,channels:loadChannels,segments:loadSegments,financial:loadFinancial,stays:loadStays,bookings:loadBookings,properties:loadProperties,import:loadImport,export:loadExport,auditlog:loadAudit,auditpanel:loadAuditPanel,validation:loadValidation,users:loadUsers}[id];if(f)f()}

async function loadDashboard(){const [d,ch,segs]=await Promise.all([api('/api/dashboard'),api('/api/analytics/channels'),api('/api/analytics/segments')]);document.getElementById('dashboard').innerHTML=`<h2>📈 Dashboard - Overview</h2><div class="cards">${[['Total',d.bookings],['Confirmed',d.confirmed],['Completed',d.completed],['Pending',d.pending],['Cancelled',d.cancelled],['Eligible Revenue',fmtVND(d.eligible_revenue)]].map(x=>`<div class="card"><div class="label">${x[0]}</div><div class="value">${x[1]}</div></div>`).join('')}</div><h3>Performance Analysis</h3><div class="grid2"><div class="chart"><h3>📊 Booking Status</h3><canvas id="dash-status"></canvas></div><div class="chart"><h3>💰 Revenue by Channel</h3><canvas id="dash-revenue"></canvas></div></div><div class="grid2"><div class="chart"><h3>👥 Customer Segments</h3><canvas id="dash-segment"></canvas></div><div class="chart"><h3>🌐 Bookings by Channel</h3><canvas id="dash-channel"></canvas></div></div><div class="notice">Scope: ${me.role==='staff'?'your own bookings':'all staff bookings'}.</div>`;mkChart('dash-status','dashStatus','doughnut',['Confirmed','Completed','Pending','Cancelled'],[d.confirmed,d.completed,d.pending,d.cancelled]);mkChart('dash-revenue','dashRevenue','bar',ch.map(x=>x.channel),ch.map(x=>x.revenue/1e6),'Revenue (M)',{indexAxis:'y'});mkChart('dash-segment','dashSegment','pie',segs.map(x=>x.segment),segs.map(x=>x.bookings));mkChart('dash-channel','dashChannel','bar',ch.map(x=>x.channel),ch.map(x=>x.bookings),'Bookings')}

async function loadStaff(){const k=await api(`/api/kpi${staffMonth?`?month=${staffMonth}`:''}`);staff=await api('/api/staff');bookings=await api(`/api/bookings${staffMonth?`?month=${staffMonth}`:''}`);const km=new Map(k.rows.map(x=>[x.staff_id,x]));const propsByStaff={};for(const b of bookings){if(b.status==='cancelled')continue;(propsByStaff[b.staff_id]??=new Map()).set(b.property_id,b.property_name)}const months=k.evidence_months||[];document.getElementById('staff').innerHTML=`<h2>👥 Staff Management</h2><div class="notice"><strong>Staff are not assigned to one fixed Property.</strong> Property coverage is derived from Bookings for the selected period. Eligible revenue uses Confirmed + Completed bookings.</div><div class="toolbar">${me.role!=='staff'?'<button class="success" onclick="openStaffModal()">➕ Add Staff</button>':''}<label><strong>Filter Month:</strong></label><select id="staff-month" onchange="staffMonth=this.value;loadStaff()"><option value="">All evidence months</option>${months.map(m=>`<option ${m===staffMonth?'selected':''}>${m}</option>`).join('')}</select><strong>Total Staff: ${staff.length}</strong></div><div class="scroll"><table><thead><tr><th>Staff ID</th><th>Name</th><th>Properties Sold</th><th>Bookings</th><th>Revenue</th><th>KPI %</th><th>Status</th><th>Actions</th></tr></thead><tbody>${staff.map(s=>{const r=km.get(s.staff_id)||{}, ps=[...(propsByStaff[s.staff_id]?.entries()||[])];return `<tr><td>${s.staff_id}</td><td>${esc(s.staff_name)}</td><td>${ps.length?ps.map(([id,n])=>`<span class="badge" title="${id}">${esc(n)}</span>`).join(' '):'—'}</td><td>${bookings.filter(b=>b.staff_id===s.staff_id).length}</td><td>${fmtVND(r.revenue||0)}</td><td>${r.revenue_score==null?'N/A':r.revenue_score.toFixed(1)+'%'}</td><td>${kpiStatus(r.composite_kpi)}</td><td>${me.role==='staff'?'—':`<button class="warn small" onclick='openStaffModal(${JSON.stringify(s)})'>Edit</button><button class="danger small" onclick="deleteStaff('${s.staff_id}')">Delete</button>`}</td></tr>`}).join('')}</tbody></table></div><h3>Staff KPI Analytics</h3><div class="grid2"><div class="chart"><h3>📊 Top 10 Staff by KPI</h3><canvas id="staff-kpi-chart"></canvas></div><div class="chart"><h3>📈 KPI Trend (All Months)</h3><canvas id="staff-trend-chart"></canvas></div></div><div class="grid2"><div class="chart"><h3>💰 Eligible Revenue Contribution</h3><canvas id="staff-revenue-chart"></canvas></div><div class="chart"><h3>🎯 Booking Count by Staff</h3><canvas id="staff-bookings-chart"></canvas></div></div>`;
const ranked=[...k.rows].sort((a,b)=>(b.composite_kpi??-1)-(a.composite_kpi??-1)).slice(0,10);mkChart('staff-kpi-chart','staffKpi','bar',ranked.map(r=>r.staff_name),ranked.map(r=>r.composite_kpi||0),'KPI',{indexAxis:'y'});mkChart('staff-revenue-chart','staffRevenue','doughnut',ranked.map(r=>r.staff_name),ranked.map(r=>r.revenue));mkChart('staff-bookings-chart','staffBookings','bar',ranked.map(r=>r.staff_name),ranked.map(r=>bookings.filter(b=>b.staff_id===r.staff_id).length),'Bookings');
if(months.length){const top=k.rows.slice(0,5);const series=[];for(const s of top){const vals=[];for(const m of months){const md=await api(`/api/kpi?month=${m}`);vals.push(md.rows.find(x=>x.staff_id===s.staff_id)?.composite_kpi||0)}series.push({label:s.staff_name,data:vals,fill:false,tension:.25})}mkMultiChart('staff-trend-chart','staffTrend','line',months,series,{plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true,max:100}}})}}
function openStaffModal(s=null){const id=s?.staff_id||'';document.getElementById('dynamic-modal').innerHTML=`<div class="modal-card"><div class="modal-head"><h2>${s?'Edit':'Add'} Staff</h2><span class="x" onclick="closeModal('dynamic-modal')">&times;</span></div><div class="form-row"><div class="form-group"><label>Staff ID</label><input id="s-id" value="${esc(id)}" ${s?'disabled':''}></div><div class="form-group"><label>Name</label><input id="s-name" value="${esc(s?.staff_name||'')}"></div></div><div class="form-row"><div class="form-group"><label>Team</label><input id="s-team" value="${esc(s?.team||'')}"></div><div class="form-group"><label>Monthly Revenue Target (VND)</label><input id="s-target" type="number" value="${s?.monthly_base_revenue_target_vnd||5000000}"></div></div><div class="form-group"><label>Active</label><select id="s-active"><option value="true" ${s?.active!==false?'selected':''}>Yes</option><option value="false" ${s?.active===false?'selected':''}>No</option></select></div><button class="success" onclick="saveStaff('${id}')">💾 Save</button></div>`;document.getElementById('dynamic-modal').style.display='block'}
async function saveStaff(existing=''){const body={staff_id:existing||document.getElementById('s-id').value.trim(),staff_name:document.getElementById('s-name').value.trim(),team:document.getElementById('s-team').value.trim(),start_date:null,active:document.getElementById('s-active').value==='true',monthly_base_revenue_target_vnd:+document.getElementById('s-target').value};try{await api(existing?`/api/staff/${existing}`:'/api/staff',{method:existing?'PUT':'POST',body});closeModal('dynamic-modal');await loadMasters();loadStaff()}catch(e){alert(e.message)}}
async function deleteStaff(id){if(!confirm(`Delete ${id}? If referenced, the backend will block deletion and you should set Active = No.`))return;try{await api(`/api/staff/${id}`,{method:'DELETE'});await loadMasters();loadStaff()}catch(e){alert(e.message)}}

async function loadKPI(){const first=await api('/api/kpi');const months=first.evidence_months||[];if(kpiMonth&&!months.includes(kpiMonth))kpiMonth='';document.getElementById('kpi').innerHTML=`<h2>🏆 Composite KPI Dashboard & Staff Ranking</h2><div class="notice">Composite KPI = Revenue 40% + Room Nights 20% + Conversion 15% + On-time Payment 15% + SLA 10%. Missing evidence remains N/A and weights are not redistributed.</div><div class="toolbar"><label><strong>Month:</strong></label><select id="kpi-month" onchange="kpiMonth=this.value;refreshKPI()"><option value="">All available months</option>${months.map(m=>`<option value="${m}" ${m===kpiMonth?'selected':''}>${m}</option>`).join('')}</select><button id="kpi-refresh-btn" onclick="refreshKPI()">🔄 Refresh Ranking</button><button class="success" onclick="exportKPI()">📥 Export Ranking CSV</button></div><div id="kpi-month-status" class="notice"></div><div id="kpi-body"></div>`;if(kpiMonth){await refreshKPI()}else{renderKPI(first)}}
async function refreshKPI(){const sel=document.getElementById('kpi-month');const btn=document.getElementById('kpi-refresh-btn');const m=sel?.value||'';kpiMonth=m;if(sel)sel.disabled=true;if(btn)btn.disabled=true;msg('kpi-month-status',`⏳ Loading KPI data for ${m||'all available months'}...`);try{const d=await api(`/api/kpi${m?`?month=${encodeURIComponent(m)}`:''}`);renderKPI(d)}catch(e){msg('kpi-month-status',`❌ ${esc(e.message)}`,'error')}finally{if(sel)sel.disabled=false;if(btn)btn.disabled=false}}
function renderKPI(d){const valid=d.rows.filter(r=>r.composite_kpi!=null).sort((a,b)=>b.composite_kpi-a.composite_kpi),avg=k=>{const a=d.rows.map(r=>r[k]).filter(v=>v!=null);return a.length?a.reduce((s,v)=>s+v,0)/a.length:0};const coverage=k=>d.rows.filter(r=>r[k]!=null).length;const periodLabel=d.month==='ALL'?'All available months':d.month;document.getElementById('kpi-month-status').innerHTML=`<strong>Selected period:</strong> ${periodLabel}. <strong>Available evidence months:</strong> ${(d.evidence_months||[]).join(', ')||'None'}.`;document.getElementById('kpi-body').innerHTML=`<div class="cards"><div class="card"><div class="label">Total Staff</div><div class="value">${d.rows.length}</div></div><div class="card"><div class="label">Scorable Staff</div><div class="value">${valid.length}</div></div><div class="card"><div class="label">Average Coverage</div><div class="value">${d.rows.length?(d.rows.reduce((s,r)=>s+r.coverage,0)/d.rows.length/5*100).toFixed(0):0}%</div></div></div><div class="grid2"><div class="chart"><h3>🏅 Top 10 Staff by Composite KPI — ${periodLabel}</h3><canvas id="kpi-rank"></canvas></div><div class="chart"><h3>📊 Average KPI Component Scores — ${periodLabel}</h3><div class="muted">Coverage: Revenue ${coverage('revenue_score')}; Room Nights ${coverage('room_nights_score')}; Conversion ${coverage('conversion_score')}; Payment ${coverage('payment_score')}; SLA ${coverage('sla_score')}</div><canvas id="kpi-components"></canvas></div></div><h3>Staff Ranking — ${periodLabel}</h3><div class="scroll"><table><thead><tr><th>Rank</th><th>Staff ID</th><th>Name</th><th>Revenue</th><th>Room Nights</th><th>Conversion</th><th>On-time Payment</th><th>SLA</th><th>Composite KPI</th><th>Status</th><th>Coverage</th></tr></thead><tbody>${[...d.rows].sort((a,b)=>(b.composite_kpi??-1)-(a.composite_kpi??-1)).map((r,i)=>`<tr><td>${r.composite_kpi==null?'—':i+1}</td><td>${r.staff_id}</td><td>${esc(r.staff_name)}</td><td>${score(r.revenue_score)}</td><td>${score(r.room_nights_score)}</td><td>${score(r.conversion_score)}</td><td>${score(r.payment_score)}</td><td>${score(r.sla_score)}</td><td>${r.composite_kpi==null?'N/A':r.composite_kpi.toFixed(1)}</td><td>${kpiStatus(r.composite_kpi)}</td><td>${r.coverage}/5</td></tr>`).join('')}</tbody></table></div>`;mkChart('kpi-rank','kpiRank','bar',valid.slice(0,10).map(r=>`${r.staff_id} ${r.staff_name}`),valid.slice(0,10).map(r=>r.composite_kpi),'Composite KPI',{indexAxis:'y',scales:{x:{beginAtZero:true,max:100}}});mkChart('kpi-components','kpiComp','bar',['Revenue','Room Nights','Conversion','On-time Payment','SLA'],['revenue_score','room_nights_score','conversion_score','payment_score','sla_score'].map(avg),'Score %',{scales:{y:{beginAtZero:true,max:100}}})}
function exportKPI(){const m=document.getElementById('kpi-month')?.value||'';download(`/api/kpi/export-csv${m?`?month=${m}`:''}`,`kpi_ranking_${m||'ALL'}_v1.0.2.csv`).catch(e=>alert(e.message))}

async function loadDataModel(){const d=await api('/api/data-model');document.getElementById('datamodel').innerHTML=`<h2>🧩 V1.0.2a Pilot Data Model</h2><div class="notice">Normalized backend entities are validated against PK/FK rules in the centralized database. Transactional history is never silently deleted by master synchronization.</div><div class="cards"><div class="card"><div class="label">Errors</div><div class="value">${d.error_count}</div></div><div class="card"><div class="label">Warnings</div><div class="value">${d.warning_count}</div></div></div><div class="toolbar"><button class="success" onclick="refreshDataModel()">🔄 Rebuild / Refresh Data Model</button><button class="purple" onclick="syncMasterDeps()">🔗 Sync Master Dependencies</button><button onclick="checkDataModel()">✅ Check Keys & Relations</button><button onclick="exportDataModelJson()">📥 Export Data Model JSON</button><button onclick="exportIntegrityCsv()">📥 Export Integrity Report CSV</button></div><div id="dm-msg"></div><div class="grid2"><div><h3>Entity Overview</h3><div class="scroll"><table><thead><tr><th>Entity</th><th>Primary Key</th><th>Rows</th><th>Status</th></tr></thead><tbody>${d.entities.map(x=>`<tr><td>${x.entity}</td><td>${x.primary_key}</td><td>${x.rows}</td><td>${d.issues.some(i=>i.entity===x.entity)?'⚠️ Review':'✅ PASS'}</td></tr>`).join('')}</tbody></table></div></div><div><h3>Relationship Rules</h3><div class="notice">Bookings.staff_id → Staff.staff_id<br>Staff ↔ Properties through Bookings<br>Bookings.property_id → Properties.property_id<br>Bookings.room_type_id → Room Types(property_id + room_type_id)<br>KPI Targets.staff_id → Staff.staff_id<br>Users.staff_id → Staff.staff_id (optional for manager/admin)</div></div></div><h3>Entity Tables</h3><div id="dm-entities"></div><h3>Integrity Issues</h3><div class="scroll"><table><thead><tr><th>Severity</th><th>Entity</th><th>Record ID</th><th>Rule</th><th>Issue</th></tr></thead><tbody>${d.issues.length?d.issues.map(i=>`<tr><td>${i.severity}</td><td>${i.entity}</td><td>${i.record_id}</td><td>${i.rule}</td><td>${esc(i.issue)}</td></tr>`).join(''):'<tr><td colspan="5">✅ No integrity issues.</td></tr>'}</tbody></table></div>`;await renderDataModelEntities()}
async function renderDataModelEntities(){const [u,s,p,c]=await Promise.all([me.role==='admin'?api('/api/users'):Promise.resolve([]),api('/api/staff'),api('/api/properties'),api('/api/channels')]);const el=document.getElementById('dm-entities');if(!el)return;el.innerHTML=`${me.role==='admin'?`<div class="chart"><h3>Users</h3><div class="scroll"><table><thead><tr><th>User ID</th><th>Name</th><th>Role</th><th>Staff ID</th><th>Active</th></tr></thead><tbody>${u.map(x=>`<tr><td>${x.username}</td><td>${esc(x.full_name)}</td><td>${x.role}</td><td>${x.staff_id||'—'}</td><td>${x.active?'Yes':'No'}</td></tr>`).join('')}</tbody></table></div></div>`:''}<div class="grid2"><div class="chart"><h3>Staff</h3><div class="scroll"><table><thead><tr><th>Staff ID</th><th>Name</th><th>Team</th><th>Target</th></tr></thead><tbody>${s.map(x=>`<tr><td>${x.staff_id}</td><td>${esc(x.staff_name)}</td><td>${esc(x.team)}</td><td>${fmtVND(x.monthly_base_revenue_target_vnd)}</td></tr>`).join('')}</tbody></table></div></div><div class="chart"><h3>Properties</h3><div class="scroll"><table><thead><tr><th>ID</th><th>Name</th><th>Status</th><th>Total Rooms</th></tr></thead><tbody>${p.map(x=>`<tr><td>${x.property_id}</td><td>${esc(x.property_name)}</td><td>${x.active?'Active':'Inactive'}</td><td>${x.total_rooms}</td></tr>`).join('')}</tbody></table></div></div></div><div class="chart"><h3>Room Types & Inventory</h3><div class="scroll"><table><thead><tr><th>Property</th><th>Room Type</th><th>Name</th><th>Quantity</th></tr></thead><tbody>${p.flatMap(x=>x.room_types.map(r=>`<tr><td>${x.property_id}</td><td>${r.room_type_id}</td><td>${esc(r.room_type_name)}</td><td>${r.quantity}</td></tr>`)).join('')}</tbody></table></div></div><div class="chart"><h3>Channels</h3><div class="scroll"><table><thead><tr><th>Channel ID</th><th>Name</th><th>Commission</th><th>SLA</th></tr></thead><tbody>${c.map(x=>`<tr><td>${x.channel_id}</td><td>${esc(x.channel_name)}</td><td>${(x.commission_rate*100).toFixed(0)}%</td><td>${x.response_sla_minutes} min</td></tr>`).join('')}</tbody></table></div></div>`}
async function refreshDataModel(){try{await loadDataModel();msg('dm-msg','✅ Data Model refreshed from the centralized database.','successbox')}catch(e){msg('dm-msg',esc(e.message),'error')}}
async function checkDataModel(){try{const d=await api('/api/data-model');await loadDataModel();const t=(d.error_count===0&&d.warning_count===0)?'✅ PK/FK check PASS — no integrity issues.':`⚠️ Integrity check completed: ${d.error_count} error(s), ${d.warning_count} warning(s).`;msg('dm-msg',t,d.error_count?'error':'successbox')}catch(e){msg('dm-msg',esc(e.message),'error')}}
async function syncMasterDeps(){try{const r=await api('/api/data-model/sync-master-dependencies',{method:'POST'});await loadDataModel();msg('dm-msg',`✅ Master dependency sync completed. Removed orphan KPI targets: ${r.removed_kpi_targets}. ${esc(r.note)}`,'successbox')}catch(e){msg('dm-msg',esc(e.message),'error')}}
async function exportDataModelJson(){try{await download('/api/data-model/export-json','data_model_v1.0.2a.json');msg('dm-msg','✅ Data Model JSON exported.','successbox')}catch(e){msg('dm-msg',esc(e.message),'error')}}
async function exportIntegrityCsv(){try{await download('/api/data-model/export-integrity-csv','data_model_integrity_v1.0.2a.csv');msg('dm-msg','✅ Integrity Report CSV exported.','successbox')}catch(e){msg('dm-msg',esc(e.message),'error')}}

async function loadChannels(){const d=await api('/api/analytics/channels');document.getElementById('channels').innerHTML=`<h2>🌐 Channel Analytics</h2><div class="cards">${d.map(x=>`<div class="card"><div class="label">${esc(x.channel)}</div><div class="value">${x.bookings}</div></div>`).join('')}</div><div class="scroll"><table><thead><tr><th>Channel</th><th>Bookings</th><th>Revenue</th><th>Avg Revenue</th><th>Commission</th></tr></thead><tbody>${d.map(x=>`<tr><td>${esc(x.channel)}</td><td>${x.bookings}</td><td>${fmtVND(x.revenue)}</td><td>${fmtVND(x.avg_revenue)}</td><td>${fmtVND(x.commission)}</td></tr>`).join('')}</tbody></table></div>`}
async function loadSegments(){const d=await api('/api/analytics/segments');document.getElementById('segments').innerHTML=`<h2>👨‍👩‍👧‍👦 Segment Analysis</h2><div class="cards">${d.map(x=>`<div class="card"><div class="label">${esc(x.segment)}</div><div class="value">${x.bookings}</div></div>`).join('')}</div><div class="scroll"><table><thead><tr><th>Segment</th><th>Bookings</th><th>Revenue</th><th>Avg Revenue</th><th>Avg Guests</th></tr></thead><tbody>${d.map(x=>`<tr><td>${esc(x.segment)}</td><td>${x.bookings}</td><td>${fmtVND(x.revenue)}</td><td>${fmtVND(x.avg_revenue)}</td><td>${Number(x.avg_guests).toFixed(1)}</td></tr>`).join('')}</tbody></table></div>`}
async function loadFinancial(){const d=await api('/api/analytics/financial');document.getElementById('financial').innerHTML=`<h2>💰 Financial Analysis</h2><div class="cards"><div class="card"><div class="label">Total Revenue</div><div class="value">${fmtVND(d.total_revenue)}</div></div><div class="card"><div class="label">Commission</div><div class="value">${fmtVND(d.commission)}</div></div><div class="card"><div class="label">Deposit Due</div><div class="value">${fmtVND(d.deposit_due)}</div></div><div class="card"><div class="label">Commission %</div><div class="value">${d.commission_pct.toFixed(2)}%</div></div></div><div class="grid2"><div class="chart"><h3>Revenue by Status</h3><canvas id="fin-status"></canvas></div><div class="chart"><h3>Commission by Channel</h3><canvas id="fin-channel"></canvas></div></div>`;mkChart('fin-status','finStatus','doughnut',Object.keys(d.revenue_by_status),Object.values(d.revenue_by_status).map(x=>x/1e6),'Revenue M');mkChart('fin-channel','finChannel','bar',Object.keys(d.commission_by_channel),Object.values(d.commission_by_channel).map(x=>x/1e6),'Commission M',{indexAxis:'y'})}
async function loadStays(){const d=await api('/api/analytics/stays');document.getElementById('stays').innerHTML=`<h2>🏨 Stay Duration Analysis</h2><div class="notice">The left chart groups bookings by nights per booking; the right groups the same bookings by guests per booking. They measure different dimensions.</div><div class="cards"><div class="card"><div class="label">Avg Nights / Booking</div><div class="value">${d.avg_nights.toFixed(2)}</div></div><div class="card"><div class="label">Avg Guests / Booking</div><div class="value">${d.avg_guests.toFixed(2)}</div></div><div class="card"><div class="label">Total Bookings</div><div class="value">${d.total_bookings}</div></div><div class="card"><div class="label">Eligible Revenue</div><div class="value">${fmtVND(d.eligible_revenue)}</div></div></div><div class="grid2"><div class="chart"><h3>Stay Duration Distribution</h3><canvas id="stay-night"></canvas></div><div class="chart"><h3>Guest Count Distribution</h3><canvas id="stay-guest"></canvas></div></div>`;mkChart('stay-night','stayNight','bar',Object.keys(d.nights_distribution),Object.values(d.nights_distribution),'Bookings');mkChart('stay-guest','stayGuest','doughnut',Object.keys(d.guest_distribution),Object.values(d.guest_distribution))}

async function loadBookings(){bookings=await api('/api/bookings');const status=document.getElementById('bookings-status-cache')?.value||'';renderBookings(status)}
function renderBookings(status=''){const rows=status?bookings.filter(b=>b.status===status):bookings;document.getElementById('bookings').innerHTML=`<h2>📅 Bookings Management (CRUD)</h2><div class="toolbar"><button class="success" onclick="openBooking()">➕ Add Booking</button><label>Filter Status:</label><select id="bookings-status-cache" onchange="renderBookings(this.value)"><option value="">All</option>${['confirmed','completed','pending','cancelled'].map(s=>`<option ${s===status?'selected':''}>${s}</option>`).join('')}</select><strong>Total: ${rows.length}</strong></div><div class="scroll"><table><thead><tr><th>ID</th><th>Staff</th><th>Property</th><th>Room Type</th><th>Channel</th><th>Check-in</th><th>Check-out</th><th>Guests</th><th>Status</th><th>Revenue</th><th>Actions</th></tr></thead><tbody>${rows.map(b=>`<tr><td>${b.booking_id}</td><td>${esc(b.staff_name)}</td><td>${esc(b.property_name)}</td><td>${b.room_type_id} - ${esc(b.room_type_name)}</td><td>${esc(b.channel)}</td><td>${b.check_in_date}</td><td>${b.check_out_date}</td><td>${b.number_of_guests}</td><td class="status-${b.status}">${b.status}</td><td>${fmtVND(b.revenue)}</td><td><button class="warn small" onclick='editBooking(${JSON.stringify(b)})'>Edit</button><button class="danger small" onclick="deleteBooking('${b.booking_id}')">Delete</button></td></tr>`).join('')}</tbody></table></div>`}
function openBooking(){fillBookingSelects();document.getElementById('booking-modal-title').textContent='Add Booking';document.getElementById('b-id').value='';document.querySelectorAll('#booking-modal input').forEach(x=>{if(x.type!=='hidden')x.value='' });document.getElementById('b-guests').value=2;document.getElementById('b-rooms').value=1;document.getElementById('b-revenue').value=0;document.getElementById('b-deposit').value=0;document.getElementById('b-date').value=isoToday();document.getElementById('b-in').value=isoToday();let t=new Date();t.setDate(t.getDate()+1);document.getElementById('b-out').value=t.toISOString().slice(0,10);document.getElementById('booking-modal').style.display='block'}
function fillBookingSelects(){document.getElementById('b-staff-wrap').classList.toggle('hidden',me.role==='staff');document.getElementById('b-staff').innerHTML=staff.map(s=>`<option value="${s.staff_id}">${s.staff_id} - ${esc(s.staff_name)}</option>`).join('');document.getElementById('b-property').innerHTML='<option value="">-- Select Property --</option>'+properties.filter(p=>p.active).map(p=>`<option value="${p.property_id}">${p.property_id} - ${esc(p.property_name)}</option>`).join('');document.getElementById('b-channel').innerHTML=channels.filter(c=>c.active).map(c=>`<option>${esc(c.channel_name)}</option>`).join('');fillRoomTypes()}
function fillRoomTypes(pref=''){const p=properties.find(x=>x.property_id===document.getElementById('b-property').value);document.getElementById('b-room').innerHTML=(p?.room_types||[]).filter(r=>r.active).map(r=>`<option value="${r.room_type_id}">${r.room_type_id} - ${esc(r.room_type_name)} (${r.quantity} rooms; max ${r.max_guests_per_room} guests/room)</option>`).join('');if(pref)document.getElementById('b-room').value=pref}
function editBooking(b){fillBookingSelects();document.getElementById('booking-modal-title').textContent=`Edit ${b.booking_id}`;document.getElementById('b-id').value=b.booking_id;if(me.role!=='staff')document.getElementById('b-staff').value=b.staff_id;document.getElementById('b-property').value=b.property_id;fillRoomTypes(b.room_type_id);[['b-date','booking_date'],['b-in','check_in_date'],['b-out','check_out_date'],['b-guests','number_of_guests'],['b-rooms','number_of_rooms'],['b-channel','channel'],['b-status','status'],['b-segment','segment'],['b-revenue','revenue'],['b-deposit','deposit_due'],['b-deposit-date','deposit_due_date'],['b-notes','notes']].forEach(([id,k])=>document.getElementById(id).value=b[k]??'');document.getElementById('booking-modal').style.display='block'}
async function saveBooking(){const id=document.getElementById('b-id').value,body={staff_id:me.role==='staff'?null:document.getElementById('b-staff').value,property_id:document.getElementById('b-property').value,room_type_id:document.getElementById('b-room').value,booking_date:document.getElementById('b-date').value,check_in_date:document.getElementById('b-in').value,check_out_date:document.getElementById('b-out').value,number_of_guests:+document.getElementById('b-guests').value,number_of_rooms:+document.getElementById('b-rooms').value,status:document.getElementById('b-status').value,channel:document.getElementById('b-channel').value,segment:document.getElementById('b-segment').value,revenue:+document.getElementById('b-revenue').value,deposit_due:+document.getElementById('b-deposit').value,deposit_due_date:document.getElementById('b-deposit-date').value||null,notes:document.getElementById('b-notes').value};try{await api(id?`/api/bookings/${id}`:'/api/bookings',{method:id?'PUT':'POST',body});closeModal('booking-modal');await loadBookings()}catch(e){alert(e.message)}}
async function deleteBooking(id){if(!confirm(`Delete ${id}? Linked payment/CRM evidence will block deletion.`))return;try{await api(`/api/bookings/${id}`,{method:'DELETE'});await loadBookings()}catch(e){alert(e.message)}}

async function loadProperties(){properties=await api('/api/properties');bookings=await api('/api/bookings');const selected=propertyFilter;const shown=selected?properties.filter(p=>p.property_id===selected):properties;const scoped=selected?bookings.filter(b=>b.property_id===selected):bookings;const rev=scoped.filter(b=>['confirmed','completed'].includes(b.status)).reduce((s,b)=>s+b.revenue,0);document.getElementById('properties').innerHTML=`<h2>🏢 Property Master & Statistics</h2><div class="notice">Room inventory is centralized in the backend. Staff can sell across multiple Properties through Booking records.</div><div class="toolbar">${me.role!=='staff'?'<button class="success" onclick="openPropertyModal()">➕ Add Property</button>':''}<label><strong>Select Property:</strong></label><select onchange="propertyFilter=this.value;loadProperties()"><option value="">All Properties</option>${properties.map(p=>`<option value="${p.property_id}" ${p.property_id===selected?'selected':''}>${p.property_id} - ${esc(p.property_name)}</option>`).join('')}</select><strong>Properties Shown: ${shown.length} / ${properties.length}</strong></div><div class="scroll"><table><thead><tr><th>Property ID</th><th>Property Name</th><th>Status</th><th>Room Types</th><th>Total Rooms</th><th>Bookings</th><th>Actions</th></tr></thead><tbody>${shown.map(p=>`<tr><td><strong>${p.property_id}</strong></td><td>${esc(p.property_name)}</td><td>${p.active?'✅ Active':'🔒 Inactive'}</td><td>${p.room_types.map(r=>`<span class="badge">${esc(r.room_type_name)} (${r.quantity})</span>`).join(' ')}</td><td>${p.total_rooms}</td><td>${bookings.filter(b=>b.property_id===p.property_id).length}</td><td>${me.role==='staff'?'—':`<button class="warn small" onclick='openPropertyModal(${JSON.stringify(p)})'>Edit</button><button class="danger small" onclick="deleteProperty('${p.property_id}')">Delete</button>`}</td></tr>`).join('')}</tbody></table></div><div class="cards"><div class="card"><div class="label">${selected?'Selected Property':'Properties'}</div><div class="value">${selected||shown.length}</div></div><div class="card"><div class="label">Bookings</div><div class="value">${scoped.length}</div></div><div class="card"><div class="label">Confirmed</div><div class="value">${scoped.filter(b=>b.status==='confirmed').length}</div></div><div class="card"><div class="label">Completed</div><div class="value">${scoped.filter(b=>b.status==='completed').length}</div></div><div class="card"><div class="label">Revenue</div><div class="value">${fmtVND(rev)}</div></div><div class="card"><div class="label">Room Inventory</div><div class="value">${shown.reduce((s,p)=>s+p.total_rooms,0)}</div></div></div><div class="grid2"><div class="chart"><h3>Revenue by Property</h3><canvas id="property-rev"></canvas></div><div class="chart"><h3>Status Distribution (Property)</h3><canvas id="property-status"></canvas></div></div>`;const rmap={};for(const p of shown)rmap[p.property_name]=scoped.filter(b=>b.property_id===p.property_id&&['confirmed','completed'].includes(b.status)).reduce((s,b)=>s+b.revenue,0)/1e6;mkChart('property-rev','propRev','bar',Object.keys(rmap),Object.values(rmap),'Revenue M',{indexAxis:'y'});mkChart('property-status','propStatus','doughnut',['Confirmed','Completed','Pending','Cancelled'],['confirmed','completed','pending','cancelled'].map(s=>scoped.filter(b=>b.status===s).length))}
function openPropertyModal(p=null){const rooms=p?.room_types||[{room_type_id:'STD',room_type_name:'Standard',quantity:1,max_guests_per_room:3,active:true}];document.getElementById('dynamic-modal').innerHTML=`<div class="modal-card wide"><div class="modal-head"><h2>${p?'Edit':'Add'} Property</h2><span class="x" onclick="closeModal('dynamic-modal')">&times;</span></div><div class="form-row"><div class="form-group"><label>Property ID</label><input id="p-id" value="${esc(p?.property_id||'')}" ${p?'disabled':''}></div><div class="form-group"><label>Property Name</label><input id="p-name" value="${esc(p?.property_name||'')}"></div></div><div class="form-row"><div class="form-group"><label>Profile</label><input id="p-profile" value="${esc(p?.profile||'')}"></div><div class="form-group"><label>Active</label><select id="p-active"><option value="true" ${p?.active!==false?'selected':''}>Yes</option><option value="false" ${p?.active===false?'selected':''}>No</option></select></div></div><h3>🛏 Room Types & Inventory</h3><div class="scroll"><table id="room-editor"><thead><tr><th>ID</th><th>Name</th><th>Quantity</th><th>Max Guests</th><th>Active</th><th></th></tr></thead><tbody>${rooms.map(r=>roomRow(r)).join('')}</tbody></table></div><div class="toolbar"><button onclick="addRoomRow()">➕ Add Room Type</button></div><button class="success" onclick="saveProperty('${p?.property_id||''}')">💾 Save Property</button></div>`;document.getElementById('dynamic-modal').style.display='block'}
function roomRow(r={}){return `<tr data-original="${esc(r.room_type_id||'')}"><td><input class="rt-id" value="${esc(r.room_type_id||'')}"></td><td><input class="rt-name" value="${esc(r.room_type_name||'')}"></td><td><input class="rt-qty" type="number" min="0" value="${r.quantity??0}"></td><td><input class="rt-cap" type="number" min="1" value="${r.max_guests_per_room??2}"></td><td><select class="rt-active"><option value="true" ${r.active!==false?'selected':''}>Yes</option><option value="false" ${r.active===false?'selected':''}>No</option></select></td><td><button class="danger small" onclick="this.closest('tr').remove()">Remove</button></td></tr>`}
function addRoomRow(){document.querySelector('#room-editor tbody').insertAdjacentHTML('beforeend',roomRow())}
async function saveProperty(existing=''){const pid=existing||document.getElementById('p-id').value.trim().toUpperCase(),body={property_id:pid,property_name:document.getElementById('p-name').value.trim(),active:document.getElementById('p-active').value==='true',profile:document.getElementById('p-profile').value.trim()};const rows=[...document.querySelectorAll('#room-editor tbody tr')].map(tr=>({original:tr.dataset.original,room_type_id:tr.querySelector('.rt-id').value.trim().toUpperCase(),room_type_name:tr.querySelector('.rt-name').value.trim(),quantity:+tr.querySelector('.rt-qty').value,max_guests_per_room:+tr.querySelector('.rt-cap').value,active:tr.querySelector('.rt-active').value==='true'})).filter(r=>r.room_type_id&&r.room_type_name);try{if(existing)await api(`/api/properties/${existing}`,{method:'PUT',body});else await api('/api/properties',{method:'POST',body});const old=properties.find(p=>p.property_id===pid)?.room_types||[];for(const r of rows){const ex=old.find(x=>x.room_type_id===r.original);if(ex)await api(`/api/properties/${pid}/room-types/${encodeURIComponent(r.original)}`,{method:'PUT',body:r});else await api(`/api/properties/${pid}/room-types`,{method:'POST',body:r})}for(const oldr of old){if(!rows.some(r=>r.original===oldr.room_type_id)){try{await api(`/api/properties/${pid}/room-types/${encodeURIComponent(oldr.room_type_id)}`,{method:'DELETE'})}catch(e){alert(`Room type ${oldr.room_type_id} was not deleted: ${e.message}`)}}}closeModal('dynamic-modal');await loadMasters();loadProperties()}catch(e){alert(e.message)}}
async function deleteProperty(id){if(!confirm(`Delete ${id}? Historical references will block deletion; use Inactive if needed.`))return;try{await api(`/api/properties/${id}`,{method:'DELETE'});await loadMasters();loadProperties()}catch(e){alert(e.message)}}

function loadImport(){document.getElementById('import').innerHTML=`<h2>📥 Excel Import & Save to App</h2><div class="notice"><strong>Direct database import:</strong> selecting an Excel workbook previews it in the browser. Clicking <strong>Import & Save to App</strong> uploads the workbook directly to FastAPI and permanently saves the imported records in SQLite/PostgreSQL. No PowerShell import command is required.</div><div class="notice"><strong>Authoritative master sync:</strong> Staff, Properties, Room_Types, Channels and KPI_Targets are master data. <strong>Replace authoritative data</strong> is recommended for a clean pilot reload. Historical records are preserved by deactivation rather than unsafe deletion where applicable.</div><div class="toolbar"><input id="excel-file" type="file" accept=".xlsx,.xls" onchange="handleExcelSelected(this.files[0])"><select id="import-mode"><option value="replace" selected>Replace authoritative data</option><option value="merge">Merge</option></select><button id="import-save-btn" class="success" onclick="importExcel()" disabled>📥 Import & Save to App</button></div><div id="import-file-status" class="notice">No workbook selected.</div><div id="import-msg"></div><h3>Import Preview — Bookings</h3><div class="scroll"><table><thead><tr><th>Booking ID</th><th>Staff</th><th>Property</th><th>Room Type</th><th>Channel</th><th>Check-in</th><th>Guests</th><th>Revenue</th></tr></thead><tbody id="import-preview"><tr><td colspan="8">Choose an Excel workbook to preview.</td></tr></tbody></table></div>`}
async function handleExcelSelected(f){const b=document.getElementById('import-save-btn');if(b)b.disabled=!f;if(!f){msg('import-file-status','No workbook selected.');return}msg('import-file-status',`Selected: <strong>${esc(f.name)}</strong> (${Math.max(1,Math.round(f.size/1024))} KB). Ready to import and save to the backend database.`,'successbox');try{await previewExcel(f)}catch(e){msg('import-msg',`Preview failed: ${esc(e.message)}. You may still try Import & Save to App.`,'error')}}
async function previewExcel(f){if(!f)return;if(typeof XLSX==='undefined'){throw new Error('Excel preview library is not loaded yet')}const buf=await f.arrayBuffer(),wb=XLSX.read(buf,{type:'array'}),ws=wb.Sheets['Bookings']||wb.Sheets[wb.SheetNames[0]],rows=XLSX.utils.sheet_to_json(ws,{defval:''}).slice(0,20);document.getElementById('import-preview').innerHTML=rows.map(r=>`<tr><td>${esc(r.bookingId||r['No.']||'')}</td><td>${esc(r.staffId||'')}</td><td>${esc(r.propertyId||'')}</td><td>${esc(r.roomTypeId||'')}</td><td>${esc(r.channel||'')}</td><td>${esc(r.checkInDate||'')}</td><td>${esc(r.numberOfGuests||'')}</td><td>${esc(r.revenue||'')}</td></tr>`).join('')||'<tr><td colspan="8">No preview rows.</td></tr>'}
async function uploadExcelToBackend(f,mode){const fd=new FormData();fd.append('file',f,f.name);const headers={};if(token)headers.Authorization=`Bearer ${token}`;const r=await fetch(`${API}/api/admin/import-excel?mode=${encodeURIComponent(mode)}`,{method:'POST',headers,body:fd});if(r.status===401){logout();throw new Error('Session expired')}let payload=null;try{payload=await r.clone().json()}catch{}if(!r.ok)throw new Error(payload?.detail||`Import failed: HTTP ${r.status}`);return payload||{}}
function importCountTable(counts={}){const order=['Staff','Properties','Room_Types','Channels','KPI_Targets','Bookings','Thanh_toan','Lead_CRM'];return `<table><thead><tr><th>Entity / Sheet</th><th>Saved rows</th></tr></thead><tbody>${order.map(k=>`<tr><td>${k}</td><td><strong>${Number(counts[k]||0)}</strong></td></tr>`).join('')}</tbody></table>`}
async function importExcel(){const input=document.getElementById('excel-file'),f=input?.files?.[0];if(!f)return alert('Choose an .xlsx or .xls file first.');const mode=document.getElementById('import-mode').value,btn=document.getElementById('import-save-btn');if(btn){btn.disabled=true;btn.textContent='⏳ Importing & saving...'}msg('import-msg',`Uploading <strong>${esc(f.name)}</strong> and saving to the centralized database. Please wait...`);try{const j=await uploadExcelToBackend(f,mode);let sync=null;try{sync=await api('/api/data-model/sync-master-dependencies',{method:'POST'})}catch(e){console.warn('Post-import master sync warning:',e)}await loadMasters();const [ready,dash]=await Promise.all([api('/api/validation/readiness'),api('/api/dashboard')]);const persisted=ready.counts||j.persisted_counts||j.counts||{};const imported=j.counts||{};const critical=['Staff','Properties','Room_Types','Channels','KPI_Targets','Bookings'];const emptyCritical=critical.filter(k=>Number(persisted[k]||0)===0&&Number(imported[k]||0)>0);if(emptyCritical.length)throw new Error(`Import returned rows but they were not persisted for: ${emptyCritical.join(', ')}`);await loadDashboard();const warnings=(j.warnings||[]).length?`<br><strong>Warnings:</strong><br>${j.warnings.map(esc).join('<br>')}`:'<br><strong>Warnings:</strong> None';const syncInfo=sync?`<br><strong>Master dependency sync:</strong> completed; removed orphan KPI targets: ${sync.removed_kpi_targets||0}.`:'';msg('import-msg',`<strong>✅ Excel imported and saved to the app database successfully.</strong><br>File: ${esc(f.name)}<br>Mode: ${esc(mode)}<br>Dashboard bookings now: <strong>${Number(dash.bookings||0)}</strong>.${syncInfo}${warnings}<div class="scroll" style="margin-top:10px">${importCountTable(persisted)}</div><div class="toolbar" style="margin-top:10px"><button onclick="showView('dashboard')">📈 Open Dashboard</button><button onclick="showView('datamodel')">🧩 Open Data Model</button><button onclick="showView('validation')">✅ Run Validation</button></div>`,'successbox')}catch(e){msg('import-msg',`<strong>❌ Import was not saved.</strong><br>${esc(e.message)}<br>Please keep the backend running and try again. No PowerShell import command should be necessary.`,'error')}finally{if(btn){btn.disabled=false;btn.textContent='📥 Import & Save to App'}}}

function loadExport(){document.getElementById('export').innerHTML=`<h2>📤 Save & Export Data</h2><div class="notice">V1.0.2 reads/writes the centralized database. There is no browser localStorage business-data source. “Save All Data” is therefore an explicit database consistency checkpoint.</div><div class="export-grid"><button class="success" onclick="saveAllCheckpoint()">💾 Save All Data in App</button><button class="success" onclick="exportExcel()">📗 Export Full Excel Workbook</button><button class="success" onclick="download('/api/export/bookings-csv','bookings_v1.0.2.csv')">📥 Bookings CSV</button><button class="success" onclick="download('/api/export/staff-csv','staff_v1.0.2.csv')">📥 Staff CSV</button><button onclick="download('/api/export/all-json','all_data_v1.0.2.json')">📥 All Data JSON</button>${me.role==='admin'?'<button class="danger" onclick="resetData()">🔄 Reset Data</button>':''}</div><div id="export-status" class="notice"><strong>Save status:</strong> Database writes are committed immediately by the backend.</div><div class="notice"><strong>Security:</strong> password hashes are never exported.</div>`}
function saveAllCheckpoint(){msg('export-status','<strong>Save status:</strong> ✅ All current CRUD operations are already committed transactionally to the database. Export can proceed.','successbox')}
async function exportExcel(){try{await download('/api/export/workbook','Non_Ecolodge_Sales_KPI_V1.0.2.xlsx')}catch(e){alert(e.message)}}
async function resetData(){if(!confirm('This clears pilot business data (Staff/Properties/Bookings/KPI etc.) but keeps user accounts. Continue?'))return;const x=prompt('Type RESET to confirm');if(x!=='RESET')return;try{const r=await api('/api/admin/reset-data?confirm=RESET',{method:'POST'});alert(r.message);await loadMasters();showView('dashboard')}catch(e){alert(e.message)}}

async function loadAudit(){const rows=await api('/api/audit');document.getElementById('auditlog').innerHTML=`<h2>📋 Audit Log - Action History</h2><div class="toolbar"><button class="success" onclick="download('/api/audit/export-csv','audit_log_v1.0.2.csv')">📥 Export Audit Log (CSV)</button></div><div class="notice">Audit records are immutable in V1.0.2. They can be filtered/exported, but not edited or deleted from the UI.</div><div class="scroll"><table><thead><tr><th>Timestamp</th><th>User</th><th>Action</th><th>Entity</th><th>ID</th><th>Details</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${a.timestamp}</td><td>${a.username}</td><td>${a.action}</td><td>${a.entity}</td><td>${a.entity_id}</td><td>${esc(a.details)}</td></tr>`).join('')}</tbody></table></div>`}
async function loadAuditPanel(){const [s,rows,users]=await Promise.all([api('/api/audit/summary'),api('/api/audit/filter'),api('/api/users')]);const actions=[...new Set(rows.map(x=>x.action))].sort();document.getElementById('auditpanel').innerHTML=`<h2>🔍 Audit Panel - Analysis & Monitoring</h2><div class="cards"><div class="card"><div class="label">Total Actions</div><div class="value">${s.total_actions}</div></div><div class="card"><div class="label">Unique Users</div><div class="value">${s.unique_users}</div></div><div class="card"><div class="label">Action Types</div><div class="value">${s.action_types}</div></div><div class="card"><div class="label">Today's Actions</div><div class="value">${s.today_actions}</div></div></div><div class="filter-box"><h3>🔎 Filters & Search</h3><div class="form-row"><div class="form-group"><label>User</label><select id="af-user"><option value="">All Users</option>${[...new Set(rows.map(x=>x.username))].sort().map(x=>`<option>${x}</option>`).join('')}</select></div><div class="form-group"><label>Action Type</label><select id="af-action"><option value="">All Actions</option>${actions.map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="form-group"><label>Date Range</label><select id="af-days"><option value="">All Dates</option><option value="1">Today / 24h</option><option value="7">Last 7 Days</option><option value="30">Last 30 Days</option></select></div><div class="toolbar"><button onclick="applyAuditFilters()">🔍 Apply Filters</button><button class="secondary" onclick="loadAuditPanel()">↺ Reset All</button><button class="success" onclick="exportAuditFiltered()">📥 Export CSV</button></div></div><h3>🔐 User Account Management</h3><div class="toolbar"><button class="success" onclick="openUserModal()">➕ Create Account & Password</button></div><div class="scroll"><table><thead><tr><th>Username</th><th>Name</th><th>Role</th><th>Staff ID</th><th>Status</th><th>Actions</th></tr></thead><tbody>${users.map(x=>userRow(x)).join('')}</tbody></table></div><h3>📋 Audit Log (Recent Activity)</h3><div id="audit-filter-results">${auditTable(rows)}</div><div class="cards">${Object.entries(s.by_action||{}).slice(0,8).map(([k,v])=>`<div class="card"><div class="label">${esc(k)}</div><div class="value">${v}</div></div>`).join('')}</div>`}
function auditTable(rows){return `<div class="scroll"><table><thead><tr><th>Timestamp</th><th>User</th><th>Action</th><th>Entity</th><th>ID</th><th>Details</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${a.timestamp}</td><td>${a.username}</td><td>${a.action}</td><td>${a.entity}</td><td>${a.entity_id}</td><td>${esc(a.details)}</td></tr>`).join('')}</tbody></table></div>`}
async function applyAuditFilters(){const u=document.getElementById('af-user').value,a=document.getElementById('af-action').value,d=document.getElementById('af-days').value;const q=new URLSearchParams();if(u)q.set('username',u);if(a)q.set('action',a);if(d)q.set('days',d);const rows=await api('/api/audit/filter?'+q);document.getElementById('audit-filter-results').innerHTML=auditTable(rows)}
function exportAuditFiltered(){const q=new URLSearchParams(),u=document.getElementById('af-user').value,a=document.getElementById('af-action').value,d=document.getElementById('af-days').value;if(u)q.set('username',u);if(a)q.set('action',a);if(d)q.set('days',d);download('/api/audit/export-csv?'+q,'audit_filtered_v1.0.2.csv').catch(e=>alert(e.message))}

async function loadValidation(){const [d,cfg,ready]=await Promise.all([api('/api/validation'),api('/api/settings/kpi-sla'),api('/api/validation/readiness')]);const chans=channels.length?channels:await api('/api/channels');document.getElementById('validation').innerHTML=`<h2>✅ Functional Validation Center</h2><div class="notice">Use this tab before every pilot session. Safe repairs do not change booking status, property, revenue, channel, or customer segment.</div><div class="cards"><div class="card"><div class="label">Gate</div><div class="value">${d.summary.gate}</div></div><div class="card"><div class="label">Errors</div><div class="value">${d.summary.errors}</div></div><div class="card"><div class="label">Warnings</div><div class="value">${d.summary.warnings}</div></div><div class="card"><div class="label">Bookings</div><div class="value">${d.summary.bookings}</div></div></div><div class="toolbar"><button class="success" onclick="loadValidation()">▶ Run Validation</button><button class="warn" onclick="repairValidation()">🛠 Repair Safe Issues</button><button onclick="download('/api/validation/export-csv','validation_v1.0.2.csv')">📥 Export Validation CSV</button></div><div class="notice ${d.summary.errors?'error':'successbox'}">${d.summary.errors?'Pilot acceptance gate failed. Review blocking issues below.':'Pilot acceptance gate passed: no blocking validation errors.'}</div><div class="grid2"><div class="chart"><h3>Validation Rules</h3><table><tbody><tr><td>Booking ID</td><td>Required and unique</td></tr><tr><td>Staff link</td><td>staff_id must exist</td></tr><tr><td>Property</td><td>property_id must exist</td></tr><tr><td>Room Type</td><td>Property + Room Type must exist and capacity must support guests</td></tr><tr><td>Dates</td><td>Check-out after check-in</td></tr><tr><td>Status</td><td>confirmed / completed / pending / cancelled</td></tr><tr><td>Channel</td><td>Approved channel</td></tr><tr><td>Segment</td><td>Leisure / Business / Group</td></tr><tr><td>KPI target</td><td>Positive revenue and room-night targets</td></tr></tbody></table></div><div class="chart"><h3>Pilot Acceptance Gate</h3><p>${d.summary.gate==='PASS'?'✅ No blocking validation errors.':'❌ Blocking errors exist.'}</p><p>Errors: ${d.summary.errors}; Warnings: ${d.summary.warnings}</p></div></div><h3>🎯 KPI Target & SLA Rules</h3><div class="grid2"><div class="chart"><div class="form-group"><label>Default Monthly Revenue Target (VND)</label><input id="cfg-rev" type="number" value="${cfg.revenue_target_vnd}"></div><div class="form-group"><label>Default Monthly Room-night Target</label><input id="cfg-rn" type="number" value="${cfg.room_night_target}"></div><div class="form-group"><label>Conversion Target (%)</label><input id="cfg-conv" type="number" value="${cfg.conversion_target_pct*100}"></div><div class="form-group"><label>On-time Payment Target (%)</label><input id="cfg-pay" type="number" value="${cfg.payment_target_pct*100}"></div><div class="form-group"><label>SLA Compliance Target (%)</label><input id="cfg-sla" type="number" value="${cfg.sla_compliance_target_pct*100}"></div></div><div class="chart"><h3>SLA Rules by Channel</h3><table><thead><tr><th>Channel</th><th>Response SLA (min)</th></tr></thead><tbody>${chans.map(c=>`<tr><td>${esc(c.channel_name)}</td><td><input class="sla-input" data-channel="${esc(c.channel_name)}" type="number" min="1" value="${cfg.sla_minutes[c.channel_name]||c.response_sla_minutes}"></td></tr>`).join('')}</tbody></table></div></div><div class="toolbar"><button class="success" onclick="saveKpiSla()">💾 Save KPI & SLA Rules</button><button onclick="loadValidation()">↺ Reload Rules</button><button class="warn" onclick="resetKpiSla()">Reset Defaults</button></div><h3>📚 Multi-sheet / Database Readiness</h3><div class="notice">${ready.last_import?`Last import: ${esc(ready.last_import.file_name)} at ${esc(ready.last_import.imported_at)} (${esc(ready.last_import.mode)})`:'No recorded workbook import metadata in this database.'}</div><div class="scroll"><table><thead><tr><th>Entity / Sheet</th><th>Rows</th><th>Status</th><th>Use</th></tr></thead><tbody>${Object.entries(ready.counts).map(([k,v])=>`<tr><td>${k}</td><td>${v}</td><td>${v>0?'✅ Ready':'⚠️ Empty'}</td><td>Centralized database evidence</td></tr>`).join('')}</tbody></table></div><h3>Validation Issues</h3><div class="scroll"><table><thead><tr><th>Severity</th><th>Entity</th><th>ID</th><th>Field</th><th>Issue</th><th>Suggested Action</th></tr></thead><tbody>${d.issues.length?d.issues.map(i=>`<tr><td>${i.severity}</td><td>${i.entity}</td><td>${i.id}</td><td>${i.field}</td><td>${esc(i.issue)}</td><td>${esc(i.suggested_action)}</td></tr>`).join(''):'<tr><td colspan="6">✅ No validation issues.</td></tr>'}</tbody></table></div>`}
async function repairValidation(){if(!confirm('Apply only safe derived-data repairs (e.g. room count capacity and invalid derived commission)?'))return;try{const r=await api('/api/validation/repair-safe',{method:'POST'});alert(`Safe repairs: ${r.repairs.length}\n${r.repairs.slice(0,20).join('\n')}`);loadValidation()}catch(e){alert(e.message)}}
async function saveKpiSla(){const sla={};document.querySelectorAll('.sla-input').forEach(x=>sla[x.dataset.channel]=+x.value);const body={revenue_target_vnd:+document.getElementById('cfg-rev').value,room_night_target:+document.getElementById('cfg-rn').value,conversion_target_pct:+document.getElementById('cfg-conv').value/100,payment_target_pct:+document.getElementById('cfg-pay').value/100,sla_compliance_target_pct:+document.getElementById('cfg-sla').value/100,sla_minutes:sla};try{await api('/api/settings/kpi-sla',{method:'PUT',body});await loadMasters();alert('KPI & SLA rules saved.');loadValidation()}catch(e){alert(e.message)}}
async function resetKpiSla(){if(!confirm('Reset KPI/SLA fallback configuration?'))return;await api('/api/settings/kpi-sla/reset',{method:'POST'});loadValidation()}

async function loadUsers(){const u=await api('/api/users');document.getElementById('users').innerHTML=`<h2>🔐 User Account Management</h2><div class="toolbar"><button class="success" onclick="openUserModal()">➕ Create Account & Password</button></div><div class="notice">Passwords are PBKDF2-SHA256 hashed on the backend and never exported. Staff accounts must link to a Staff ID.</div><div class="scroll"><table><thead><tr><th>Username</th><th>Name</th><th>Role</th><th>Staff ID</th><th>Status</th><th>Actions</th></tr></thead><tbody>${u.map(x=>userRow(x)).join('')}</tbody></table></div>`}
function userRow(x){return `<tr><td>${x.username}</td><td>${esc(x.full_name)}</td><td>${x.role}</td><td>${x.staff_id||'—'}</td><td>${x.active?'✅ Active':'🔒 Disabled'}</td><td><button class="warn small" onclick='openUserModal(${JSON.stringify(x)})'>Password / Edit</button><button class="secondary small" onclick='toggleUser(${JSON.stringify(x)})'>${x.active?'Disable':'Enable'}</button>${x.id===me.id?'':`<button class="danger small" onclick="deleteUser(${x.id})">Delete</button>`}</td></tr>`}
function openUserModal(u=null){document.getElementById('u-staff').innerHTML='<option value="">-- none --</option>'+staff.map(s=>`<option value="${s.staff_id}">${s.staff_id} - ${esc(s.staff_name)}</option>`).join('');document.getElementById('u-username').value=u?.username||'';document.getElementById('u-name').value=u?.full_name||'';document.getElementById('u-password').value='';document.getElementById('u-role').value=u?.role||'staff';document.getElementById('u-staff').value=u?.staff_id||'';document.getElementById('user-modal').dataset.id=u?.id||'';document.querySelector('#user-modal h2').textContent=u?'Edit Account / Password':'Create Account';document.getElementById('user-modal').style.display='block'}
async function saveUser(){const id=document.getElementById('user-modal').dataset.id,body={username:document.getElementById('u-username').value,full_name:document.getElementById('u-name').value,password:document.getElementById('u-password').value||null,role:document.getElementById('u-role').value,staff_id:document.getElementById('u-staff').value||null,active:true};try{if(!id&&!body.password)return alert('Password is required for a new account');await api(id?`/api/users/${id}`:'/api/users',{method:id?'PUT':'POST',body});closeModal('user-modal');await loadUsers()}catch(e){alert(e.message)}}
async function toggleUser(u){const body={username:u.username,full_name:u.full_name,password:null,role:u.role,staff_id:u.staff_id,active:!u.active};try{await api(`/api/users/${u.id}`,{method:'PUT',body});loadUsers()}catch(e){alert(e.message)}}
async function deleteUser(id){if(!confirm('Delete this user account?'))return;try{await api(`/api/users/${id}`,{method:'DELETE'});loadUsers()}catch(e){alert(e.message)}}

boot();
